using System.Linq;

public static class MatrixCornerValue
{
    public static int MatrixCornerValue(string[] values)
    {
        return values.Count();
    }
}

solutionCode:
using System.Linq;

public static class MatrixCornerValue
{
    public static int MatrixCornerValue(string[] values)
    {
        return values.Distinct().Count();
    }
}
